                                                                                                                                                                                                                    
  CREATE TABLE "TENANT_EVENT_MESSAGE_BOARD"                                                                                                                                                              
   (	"EVENT_MESSAGE_BOARD_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                         
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                              
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                         
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                
	"EVENT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                           
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                
	"EXT_USER_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                        
	"CONTENT" CLOB NOT NULL ENABLE,                                                                                                                                                                                    
	"TYPE" NVARCHAR2(20) DEFAULT 'COMMENT' NOT NULL ENABLE,                                                                                                                                                            
	"IMAGES_URL" NVARCHAR2(2000),                                                                                                                                                                                      
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                      
	 CONSTRAINT "TYPE_OPTIONAL_VALUES" CHECK ( TYPE in ('COMMENT','SYSTEM_NOTIFY','COMMENT_HAVE_IMAGE')) ENABLE,                                                                                                       
	 PRIMARY KEY ("EVENT_MESSAGE_BOARD_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                               
   ) ;                                                                                                                                                                                                              

